import type { RGBA } from '../../../ir/types';

export const FILE_HEADER = `// GENERATED FILE - do not edit by hand.
// Generated by Varcast.

`;

export function colorLiteral(rgba: RGBA): string {
  const a = byte(rgba.a);
  const r = byte(rgba.r);
  const g = byte(rgba.g);
  const b = byte(rgba.b);
  return `Color(0x${hex(a)}${hex(r)}${hex(g)}${hex(b)})`;
}

export function floatLiteral(n: number): string {
  if (!Number.isFinite(n)) return '0f';
  const rounded = Math.round(n * 10000) / 10000;
  return `${formatNumber(rounded)}f`;
}

export function stringLiteral(s: string): string {
  return JSON.stringify(s);
}

export function boolLiteral(b: boolean): string {
  return b ? 'true' : 'false';
}

export function packageLine(namespace: string): string {
  return `package ${namespace}\n\n`;
}

export function internalPackageLine(namespace: string): string {
  return `package ${namespace}.internal\n\n`;
}

export function subPackageLine(namespace: string, subPackage: string): string {
  return `package ${namespace}.${subPackage}\n\n`;
}

function byte(n: number): number {
  return Math.max(0, Math.min(255, Math.round(n * 255)));
}

function hex(n: number): string {
  return n.toString(16).toUpperCase().padStart(2, '0');
}

function formatNumber(n: number): string {
  if (Number.isInteger(n)) return String(n);
  return String(n).replace(/\.?0+$/, '');
}
